{"content": "{
  "act_one": {
    "description": "第一幕：建立世界观和人物关系。两人被困录音棚，发现人声诱饵机制。他用摩斯密码通过耳机指导她，她误以为是系统AI。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "黑暗中的声音",
        "core_event": "苏念在录音棚被丧尸围困，意外发现可以通过人声诱饵机制引开它们。",
        "emotional_tone": "紧张，求生",
        "key_scenes": ["苏念独自在录音棚醒来，听见外面的丧尸嘶吼", "她发现自己是盲人，听力异常敏锐", "摸索中发现录音设备可以播放人声诱饵"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "另一个幸存者",
        "core_event": "沈迟从通风管道出现，两人在黑暗中建立最初的信任。",
        "emotional_tone": "警惕，试探",
        "key_scenes": ["沈迟从通风管道进入录音棚", "两人在黑暗中初次交流（他无法说话，她以为他是哑巴）", "他递给她一个耳机']
      },
      {
        "chapter_number": 3,
        "chapter_title": "系统上线",
        "core_event": "耳机里传来有节奏的敲击声，苏念以为这是录音棚的智能系统。",
        "emotional_tone": "依赖建立",
        "key_scenes": ["耳机里传来摩斯密码，她理解为'系统指令'", "她根据指令调整诱饵音频，成功引开丧尸", "她对这个'系统'产生依赖"]
      },
      {
        "chapter_number": 4,
        "chapter_title": "第一次合作",
        "core_event": "两人配合使用人声诱饵，度过第一次危机。",
        "emotional_tone": "微光，温暖",
        "key_scenes": ["大批丧尸聚集在录音棚门口", "他用摩斯密码引导她调整诱饵频率", "危机解除后，她第一次对这个'系统'说谢谢"]
      }
    ],
    "turning_point": "苏念开始依赖耳机里的'系统'，将其视为黑暗中的唯一依靠。她不知道那是沈迟用摩斯密码在保护她。"
  },
  "act_two": {
    "description": "第二幕：情感升温但危机加剧。她逐渐对他产生感情，但因为误解（以为他只是冷漠的哑巴幸存者）无法开口。他默默守护，用摩斯密码传递的从来只是指令，不是爱意。中点揭示他是失声而非哑巴，但原因不明。",
    "key_chapters": [
      {
        "chapter_number": 5,
        "chapter_title": "昼夜交替",
        "core_event": "两人在录音棚度过第一个完整的昼夜，简单分享食物。",
        "emotional_tone": "平静，暗流",
        "key_scenes": ["他们轮流守夜，在黑暗中等待天明", "她听到他走动的脚步声，判断他在距离她三米的地方坐下", "她第一次主动说话，他只是点头（她以为）"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "他的名字",
        "core_event": "苏念通过耳机询问'系统'他的名字，得到的回答是他的真名。",
        "emotional_tone": "疑惑，探究",
        "key_scenes": ["她问系统：那个哑巴叫什么名字", "耳机里传来缓慢的摩斯密码：S-H-E-N  C-H-I", "她第一次知道他的名字']
      },
      {
        "chapter_number": 7,
        "chapter_title": "中点揭示：失声",
        "core_event": "苏念发现沈迟不是哑巴，而是失声——声带受损。",
        "emotional_tone": "震惊，困惑",
        "key_scenes": ["她无意间碰到他的喉咙，感觉到异常", "她问他：你不能说话吗？他的身体僵硬", "她以为这是天生的缺陷，没有追问"]
      },
      {
        "chapter_number": 8,
        "chapter_title": "物资耗尽",
        "core_event": "录音棚里的食物和水即将耗尽，他们必须想办法离开。",
        "emotional_tone": "危机逼近",
        "key_scenes": ["她发现最后的水只够支撑两天", "耳机里的指令变得简短急促", "他开始频繁查看大门"]
      },
      {
        "chapter_number": 9,
        "chapter_title": "他的体温",
        "core_event": "一个寒冷的夜晚，她不自觉地靠近他取暖。",
        "emotional_tone": "心动，酸涩",
        "key_scenes": ["她在黑暗中发抖", "他犹豫了很久，把外套搭在她身上", "她想问什么，但最终只是说：谢谢"]
      },
      {
        "chapter_number": 10,
        "chapter_title": "诱饵失效",
        "core_event": "人声诱饵机制开始失效，丧尸不再被引走。",
        "emotional_tone": "恐惧，绝望",
        "key_scenes": ["她发现同样的频率已经无法吸引丧尸", "耳机里的摩斯密码变得前所未有的急促", "大门外传来更密集的撞击声"]
      },
      {
        "chapter_number": 11,
        "chapter_title": "他做了什么决定",
        "core_event": "沈迟在黑暗中写下计划，她不知道那是什么。",
        "emotional_tone": "沉重，预感",
        "key_scenes": ["她听到他在桌子上写写画画", "耳机里传来一段很长的摩斯密码，但她只理解了部分", "她问：你要做什么？没有回答"]
      }
    ],
    "turning_point": "人声诱饵失效，丧尸即将攻入。他决定牺牲自己让她活下去。她还一无所知，以为他只是去找新的逃生路线。"
  },
  "act_three": {
    "description": "第三幕：终局与最后的告白。丧尸攻破大门，他开门引走尸群。她在绝望中按下录音笔开关，听到他三年前（失声前）录好的告白。所有的误会解开，但她永远失去了他。",
    "key_chapters": [
      {
        "chapter_number": 12,
        "chapter_title": "最后一夜",
        "core_event": "大门被攻破的那个夜晚，他做出了最终决定。",
        "emotional_tone": "悲伤，倒计时",
        "key_scenes": ["大门被撞得快要散架", "她紧紧握着耳机，仿佛那是唯一的依靠", "他站起身，走向大门"]
      },
      {
        "chapter_number": 13,
        "chapter_title": "开门",
        "core_event": "他打开门，走出去，用自己做诱饵引走丧尸。",
        "emotional_tone": "毁灭，诀别",
        "key_scenes": ["她听到门被打开的声音", "耳机里传来最后的摩斯密码：活下去", "她终于意识到什么，伸出手却只抓到空气"]
      },
      {
        "chapter_number": 14,
        "chapter_title": "他的秘密",
        "core_event": "她发现他留下的录音笔，开始听到一切。",
        "emotional_tone": "崩溃，迟来的真相",
        "key_scenes": ["她在黑暗中摸索，找到他留下的录音笔", "按下播放键，里面传来一个陌生的、温柔的声音", "那是他三年前还没失声时录好的']
      },
      {
        "chapter_number": 15,
        "chapter_title": "三年前的告白",
        "core_event": "录音笔里的内容揭示了一切——他不是陌生人，他们在前世就认识了。",
        "emotional_tone": "绝望，宿命",
        "key_scenes": ["他说着三年前想对她说的话", "他提到那个声音：'如果你听到这段录音，说明我又没能保护好你'", "她终于明白耳机里的从来不是系统"]
      },
      {
        "chapter_number": 16,
        "chapter_title": "余音",
        "core_event": "她独自在录音棚里活下去，带着他的记忆。",
        "emotional_tone": "永恒的失去",
        "key_scenes": ["天亮了，丧尸已经散去", "她抱着录音笔，坐在他最后坐的位置", "耳机里再也没有摩斯密码，只有风声"]
      }
    ],
    "turning_point": "她听到录音笔里的告白才知道一切——他认识她，他爱她，他为她失声，他为她而死。而她永远无法告诉他，她也爱他。"
  }
}
